begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
set local timezone='UTC';
select no_plan();
select ok((select count(*)=6 and bool_and(prosecdef and 'search_path=""'=any(proconfig)) from pg_proc
 where pronamespace='public'::regnamespace and proname like 'community_moderation_%'),'six moderation RPCs pin security-definer paths');
select ok((select bool_and(has_function_privilege('authenticated',oid,'EXECUTE') and not has_function_privilege('anon',oid,'EXECUTE')
 and not has_function_privilege('service_role',oid,'EXECUTE')) from pg_proc where pronamespace='public'::regnamespace and proname like 'community_moderation_%'),
 'only current authenticated sessions can invoke moderation RPCs');
select ok((select bool_and(not has_function_privilege(r,oid,'EXECUTE')) from pg_proc cross join unnest(array['anon','authenticated','service_role'])r
 where pronamespace='private'::regnamespace and proname like 'moderation_%'),'private moderation helpers are not callable');
select ok((select bool_and(not has_table_privilege(r,t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')) from unnest(array['anon','authenticated','service_role'])r
 cross join unnest(array['private.moderation_operations','private.moderation_notices'])t),'receipts and decisions have no raw API access');
select is((select count(*) from private.community_policy),0::bigint,'moderation never activates thresholds');
select is((select count(*) from private.notification_policy),0::bigint,'moderation never activates provider policy');
select is((select count(*) from private.moderation_notices),0::bigint,'migration does not manufacture historical notices');
select ok(not has_table_privilege('authenticated','public.replies','SELECT'),'reply IDs do not grant raw fan content');
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('c6200000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email,raw_user_meta_data) select pg_temp.id(n),'moderation-unit-'||n||'@example.invalid','{}'::jsonb from generate_series(1,10)n;
update public.profiles set call_name='가상신고팬',onboarding_completed_at=clock_timestamp() where id::text like 'c6200000-%';
update public.profiles set role='admin' where id=pg_temp.id(4);
update public.profiles set role='artist' where id in(pg_temp.id(5),pg_temp.id(6));
update public.profiles set is_restricted=true where id=pg_temp.id(8);
update public.profiles set is_restricted=true,restricted_until=clock_timestamp()-interval '1 second' where id=pg_temp.id(9);
update public.profiles set onboarding_completed_at=null where id=pg_temp.id(10);
update public.profiles set role='artist',onboarding_completed_at=null where id=pg_temp.id(7);
insert into public.artists(id,slug,name,grade,status) values(pg_temp.id(101),'moderation-unit','Fictional moderation artist','B','active');
insert into public.artist_members(artist_id,user_id) values(pg_temp.id(101),pg_temp.id(5)),(pg_temp.id(101),pg_temp.id(6)),(pg_temp.id(101),pg_temp.id(7));
insert into public.posts(id,artist_id,user_id,request_id,title,body) select pg_temp.id(n),pg_temp.id(101),pg_temp.id(1),pg_temp.id(n+1000),'Fictional post','Fictional body' from generate_series(201,205)n;
insert into public.comments(id,post_id,user_id,request_id,body) values(pg_temp.id(301),pg_temp.id(202),pg_temp.id(1),pg_temp.id(1301),'Fictional comment');
update public.posts set comment_count=1 where id=pg_temp.id(202);
insert into public.subscriptions(id,user_id,artist_id,provider,status,first_started_at,episode_started_at,current_period_start,current_period_end)
values(pg_temp.id(501),pg_temp.id(1),pg_temp.id(101),'toss','expired',now()-interval '2 days',now()-interval '2 days',now()-interval '2 days',now()-interval '1 day');
insert into public.replies(id,user_id,artist_id,subscription_id,body,is_blocked) select pg_temp.id(n),pg_temp.id(1),pg_temp.id(101),pg_temp.id(501),'Fictional private reply',n=402 from generate_series(401,403)n;
create temporary table moderation_context(key text primary key,data jsonb);
grant all on moderation_context to authenticated,service_role;
create function pg_temp.report(p_op integer default 601,p_type public.report_target default 'post',p_target integer default 201,p_reason text default 'Fictional report')
returns jsonb language sql as $$select public.community_moderation_report(pg_temp.id(p_op),p_type,pg_temp.id(p_target),p_reason)$$;
create function pg_temp.resolve(p_op integer,p_key text,p_revision bigint,p_decision text default 'restore',p_confirmed boolean default true)
returns jsonb language sql as $$select public.community_moderation_resolve(pg_temp.id(p_op),(select (data->>'id')::uuid from moderation_context where key=p_key),p_revision,p_decision,'Fictional review',p_confirmed)$$;
set local role anon;
select throws_ok($$select pg_temp.report()$$,'42501',null,'anonymous report denied');
select throws_ok($$select public.community_moderation_queue()$$,'42501',null,'anonymous review denied');
select throws_ok($$select public.community_moderation_notices()$$,'42501',null,'anonymous notices denied');
reset role;
set local role service_role;
select throws_ok($$select pg_temp.report()$$,'42501',null,'service cannot forge browser report');
select throws_ok($$select public.community_moderation_queue()$$,'42501',null,'service cannot impersonate admin queue');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(2)::text,true);
select throws_ok($$select pg_temp.report()$$,'55000','COMMUNITY_POLICY_REQUIRED','new report fails closed without approved policy');
select throws_ok($$select public.community_moderation_context('post',pg_temp.id(201))$$,'55000','COMMUNITY_POLICY_REQUIRED','form cannot invent reason limit');
select throws_ok($$select public.community_moderation_queue()$$,'42501','COMMUNITY_FORBIDDEN','fan cannot inspect reporter evidence');
select is(public.community_moderation_notices()->'notices','[]'::jsonb,'new actor has an honest empty decision inbox');
reset role;
insert into private.community_policy(version,max_title_length,max_body_length,max_comment_length,max_reason_length,max_images,max_image_bytes,max_image_long_edge,auto_hide_report_count,rate_window_seconds,max_contributions_per_window,max_reports_per_window,forbidden_terms,forbidden_patterns)
values('fictional-moderation-tests',100,1000,100,100,3,10000,2048,2,60,100,100,array['blockedword'],'{}');
set local role authenticated;
select is(public.community_moderation_context('post',pg_temp.id(201))->>'max_reason_length','100','report form uses approved reason limit');
select is(public.community_moderation_context('post',pg_temp.id(201))->'existing_report','null'::jsonb,'first report has no fabricated receipt');
select throws_ok($$select pg_temp.report(p_op=>null)$$,'22023','BOARD_INVALID_INPUT','operation identity required');
select throws_ok($$select pg_temp.report(p_reason=>null)$$,'23514','COMMUNITY_CONTENT_INVALID','null reason rejected');
select throws_ok($$select pg_temp.report(p_reason=>' ')$$,'23514','COMMUNITY_CONTENT_INVALID','blank reason rejected');
select throws_ok($$select pg_temp.report(p_reason=>repeat('a',101))$$,'23514','COMMUNITY_CONTENT_INVALID','approved reason bound enforced');
select throws_ok($$select pg_temp.report(p_reason=>'BLOCKEDWORD')$$,'23514','COMMUNITY_CONTENT_BLOCKED','approved prohibited text check retained');
select throws_ok($$select pg_temp.report(p_target=>999)$$,'42501',null,'nonexistent post cannot create orphan report');
select throws_ok($$select pg_temp.report(p_type=>'reply',p_target=>401)$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','arbitrary fan cannot guess another private reply');
insert into moderation_context values('first',pg_temp.report());
select is(pg_temp.report(),(select data from moderation_context where key='first'),'exact report replay returns immutable receipt');
select is((select string_agg(k,',' order by k) from jsonb_object_keys(pg_temp.report())k),'id,target_id,target_type','receipt contains no private target or reporter content');
select throws_ok($$select pg_temp.report(p_reason=>'Changed reason')$$,'23505','MODERATION_OPERATION_CONFLICT','operation payload cannot change');
select throws_ok($$select pg_temp.report(p_op=>602,p_reason=>'Changed reason')$$,'23505','MODERATION_OPERATION_CONFLICT','new key cannot rewrite lifetime evidence');
select is(public.community_moderation_context('post',pg_temp.id(201))->'existing_report'->>'status','open','own context shows current report status');
select set_config('request.jwt.claim.sub',pg_temp.id(3)::text,true);
insert into moderation_context values('second',pg_temp.report());
select is(public.community_moderation_context('post',pg_temp.id(201))->'existing_report'->>'status','hidden','threshold winner can recover hidden target report');
select is(pg_temp.report(),(select data from moderation_context where key='second'),'hidden-target exact replay does not resubmit');
select set_config('request.jwt.claim.sub',pg_temp.id(7)::text,true);
select throws_ok($$select pg_temp.report(699,'reply',403)$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','assigned artist without completed onboarding cannot newly report private replies');
select throws_ok($$select pg_temp.report()$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','new distinct reporter cannot access hidden target');
select set_config('request.jwt.claim.sub',pg_temp.id(1)::text,true);
select throws_ok($$select pg_temp.report(p_target=>202)$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','owner cannot self-report');
reset role;
select is((select report_count from public.posts where id=pg_temp.id(201)),2,'exact reports counted only once per identity');
select is((select reports from private.community_rate_limits where user_id=pg_temp.id(2)),1,'exact replay consumes no duplicate quota');
select is((select count(*) from public.reports where target_id=pg_temp.id(201) and status='hidden'),2::bigint,'all current-cycle reports synchronize to hidden');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(4)::text,true);
select is(jsonb_array_length(public.community_moderation_queue()->'reports'),2,'admin queue projects real report rows');
select is(public.community_moderation_queue()->'reports'->0->'target'->>'post_id',pg_temp.id(201)::text,'post review keeps route target linkage');
select is(public.community_moderation_queue()->'reports'->0->'target'->'owner'->>'can_restrict','true','admin review derives restriction eligibility');
select ok(not public.community_moderation_queue()::text ~ 'example.invalid|reporter_id|phone|nickname','review omits unrelated account and reporter identity fields');
select throws_ok($$select public.community_moderation_queue(0)$$,'22023','BOARD_INVALID_INPUT','zero page rejected');
select throws_ok($$select public.community_moderation_queue(101)$$,'22023','BOARD_INVALID_INPUT','unbounded page rejected');
select throws_ok($$select public.community_moderation_queue(1,now(),null)$$,'22023','BOARD_INVALID_INPUT','half cursor rejected');
select throws_ok($$select public.community_moderation_queue(1,'infinity',pg_temp.id(1))$$,'22023','BOARD_INVALID_INPUT','infinite cursor rejected');
insert into moderation_context values('queue',public.community_moderation_queue(1));
select is(jsonb_array_length((select data->'reports' from moderation_context where key='queue')),1,'queue honors bounded page');
select ok((select data->'next_cursor'<>'null'::jsonb from moderation_context where key='queue'),'queue advertises actual lookahead');
select is(jsonb_array_length(public.community_moderation_queue(1,(select (data->'next_cursor'->>'created_at')::timestamptz from moderation_context where key='queue'),(select (data->'next_cursor'->>'id')::uuid from moderation_context where key='queue'))->'reports'),1,'queue cursor retains second report without duplicate');
select throws_ok($$select pg_temp.resolve(701,'first',3,p_confirmed=>false)$$,'22023','MODERATION_CONFIRMATION_REQUIRED','resolution requires explicit confirmation');
select throws_ok($$select pg_temp.resolve(701,'first',1)$$,'40001','MODERATION_REVISION_CONFLICT','review rejects stale target revision');
insert into moderation_context values('restore',pg_temp.resolve(701,'first',3));
select is(pg_temp.resolve(701,'first',3),(select data from moderation_context where key='restore'),'exact restore retry preserves receipt despite changed revision');
select throws_ok($$select pg_temp.resolve(701,'first',3,'delete')$$,'23505','MODERATION_OPERATION_CONFLICT','uncertain restore cannot turn into delete');
select throws_ok($$select pg_temp.resolve(702,'first',4)$$,'55000','MODERATION_REPORT_RESOLVED','new operation cannot re-resolve historical report');
select set_config('request.jwt.claim.sub',pg_temp.id(2)::text,true);
select is(public.community_moderation_notices()->'notices'->0->>'decision','restored','reporter receives in-app restored decision');
select is((select string_agg(k,',' order by k) from jsonb_object_keys(public.community_moderation_notices()->'notices'->0)k),'created_at,decision,id,report_id','notice reveals only own reference and decision');
select is(pg_temp.report(),(select data from moderation_context where key='first'),'resolved reporter keeps lifetime original receipt');
select set_config('request.jwt.claim.sub',pg_temp.id(7)::text,true);
select is(public.community_moderation_notices()->'notices','[]'::jsonb,'other recipient cannot inspect decisions');
insert into moderation_context values('third',pg_temp.report());
reset role;
select is((select report_count from public.posts where id=pg_temp.id(201)),3,'new distinct reporter increments lifetime count');
select is((select is_hidden from public.posts where id=pg_temp.id(201)),false,'resolved prior cycle does not immediately re-hide target');
select is((select count(*) from private.moderation_notices),2::bigint,'restore queues exactly one notice per resolved reporter');
select throws_ok($$update private.moderation_notices set decision='deleted'$$,'55000','MODERATION_RECORD_IMMUTABLE','decision history is immutable');
select throws_ok($$truncate private.moderation_notices$$,'55000','MODERATION_RECORD_IMMUTABLE','decision history cannot truncate');
select throws_ok($$update private.moderation_operations set response='{}'$$,'55000','MODERATION_RECORD_IMMUTABLE','operation receipts cannot rewrite');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(4)::text,true);
insert into moderation_context values('delete',pg_temp.resolve(703,'third',5,'delete'));
select is(pg_temp.resolve(701,'first',3),(select data from moderation_context where key='restore'),'earlier exact restore receipt survives a later deletion without resurrecting');
select set_config('request.jwt.claim.sub',pg_temp.id(2)::text,true);
select is(jsonb_array_length(public.community_moderation_notices()->'notices'),2,'later delete appends decision rather than rewriting old notice');
select is(public.community_moderation_context('post',pg_temp.id(201))->'existing_report'->>'status','deleted','deleted target still allows own receipt context');
select throws_ok($$select public.community_moderation_notices(0)$$,'22023','BOARD_INVALID_INPUT','notice page validates bounds');
select throws_ok($$select public.community_moderation_notices(1,null,pg_temp.id(1))$$,'22023','BOARD_INVALID_INPUT','notice cursor cannot omit timestamp');
insert into moderation_context values('notice-page',public.community_moderation_notices(1));
select is(jsonb_array_length(public.community_moderation_notices(1,(select (data->'next_cursor'->>'created_at')::timestamptz from moderation_context where key='notice-page'),(select (data->'next_cursor'->>'id')::uuid from moderation_context where key='notice-page'))->'notices'),1,'notice cursor preserves second immutable decision');
-- Comment hide/restore retains exact parent counters, including legacy paths.
insert into moderation_context values('comment',pg_temp.report(610,'comment',301));
select set_config('request.jwt.claim.sub',pg_temp.id(3)::text,true);
select lives_ok($$select pg_temp.report(610,'comment',301)$$,'second distinct comment report crosses approved threshold');
reset role;
select is((select comment_count from public.posts where id=pg_temp.id(202)),0,'hidden comment decrements parent exactly once');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(4)::text,true);
select lives_ok($$select pg_temp.resolve(710,'comment',3)$$,'review restores hidden comment');
reset role;
select is((select comment_count from public.posts where id=pg_temp.id(202)),1,'restored comment increments parent once');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(5)::text,true);
select is(jsonb_array_length(public.artist_reply_activity_context('moderation-unit')->'replies'),2,'assigned artist sees unblocked replies before moderation');
reset role;
update public.replies set created_at=clock_timestamp()+interval '1 day' where id=pg_temp.id(403);
set local role authenticated;
select throws_ok($$select pg_temp.report(621,'reply',403)$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','future private reply is not reportable before visible time');
reset role;
update public.replies set created_at=now() where id=pg_temp.id(403);
set local role authenticated;
select throws_ok($$select pg_temp.report(620,'reply',402)$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','independently blocked reply is not reportable');
insert into moderation_context values('reply',pg_temp.report(620,'reply',401));
select set_config('request.jwt.claim.sub',pg_temp.id(6)::text,true);
select lives_ok($$select pg_temp.report(620,'reply',401)$$,'assigned teammate contributes a distinct reply report');
select is(jsonb_array_length(public.artist_reply_activity_context('moderation-unit')->'replies'),1,'auto-hidden reply disappears from artist content projection');
reset role;
select is((select is_blocked from public.replies where id=pg_temp.id(401)),false,'report hiding does not rewrite independent send-policy block');
select is((select is_hidden from public.replies where id=pg_temp.id(401)),true,'reply moderation uses its own hidden flag');
set local role service_role;
select is((select count(*) from public.messaging_list_replies(pg_temp.id(5),pg_temp.id(101),100)),1::bigint,'old service projection also excludes moderated reply');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(4)::text,true);
select lives_ok($$select pg_temp.resolve(720,'reply',3)$$,'admin restores reported reply');
select lives_ok($$select public.community_moderate('reply',pg_temp.id(402),'restore','Preserve independent block')$$,'legacy reply restoration is implemented');
reset role;
select is((select is_blocked from public.replies where id=pg_temp.id(402)),true,'restoration never clears independent policy block');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(5)::text,true);
select is(jsonb_array_length(public.artist_reply_activity_context('moderation-unit')->'replies'),2,'restore exposes only genuinely visible replies');
select is(public.community_moderation_notices()->'notices'->0->>'decision','restored','reply reporter receives own decision');
select set_config('request.jwt.claim.sub',pg_temp.id(4)::text,true);
select lives_ok($$select public.community_moderate('reply',pg_temp.id(401),'delete','Terminal private reply deletion')$$,'legacy reply delete synchronizes reports and notices');
select throws_ok($$select public.community_moderate('reply',pg_temp.id(401),'restore','Forbidden resurrection')$$,'55000','COMMUNITY_DELETED_TERMINAL','deleted reply cannot be restored');
reset role;
select is((select body from public.replies where id=pg_temp.id(401)),'Fictional private reply','soft deletion retains evidence instead of physical deletion');
select is((select count(*) from public.reports where target_type='reply' and target_id=pg_temp.id(401) and status='deleted'),2::bigint,'reply deletion synchronizes every report');
select is((select count(*) from private.moderation_notices where report_id=(select (data->>'id')::uuid from moderation_context where key='reply')),2::bigint,'reply restore and delete are separate immutable notices');
-- Current restriction authority and time-limited expiry; no roles are changed.
insert into moderation_context values('user',jsonb_build_object('updated_at',(select updated_at from public.profiles where id=pg_temp.id(2))));
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(4)::text,true);
select throws_ok($$select public.community_moderation_restrict(pg_temp.id(730),pg_temp.id(2),(select (data->>'updated_at')::timestamptz from moderation_context where key='user'),true,clock_timestamp()+interval '1 hour','Reason',false)$$,'22023','MODERATION_CONFIRMATION_REQUIRED','restriction requires confirmation');
select throws_ok($$select public.community_moderation_restrict(pg_temp.id(730),pg_temp.id(2),(select (data->>'updated_at')::timestamptz from moderation_context where key='user'),true,null,'Reason',true)$$,'23514','COMMUNITY_RESTRICTION_INVALID','indefinite invented restriction denied');
insert into moderation_context values('restriction-until',jsonb_build_object('until',clock_timestamp()+interval '1 hour'));
insert into moderation_context values('restriction',public.community_moderation_restrict(pg_temp.id(730),pg_temp.id(2),(select (data->>'updated_at')::timestamptz from moderation_context where key='user'),true,(select (data->>'until')::timestamptz from moderation_context where key='restriction-until'),'Reason',true));
select is(public.community_moderation_restrict(pg_temp.id(730),pg_temp.id(2),(select (data->>'updated_at')::timestamptz from moderation_context where key='user'),true,(select (data->>'until')::timestamptz from moderation_context where key='restriction-until'),'Reason',true),(select data from moderation_context where key='restriction'),'restriction replay precedes stale profile CAS and does not extend duration');
select throws_ok($$select public.community_moderation_restrict(pg_temp.id(731),pg_temp.id(2),(select (data->>'updated_at')::timestamptz from moderation_context where key='user'),false,null,'Reason',true)$$,'40001','MODERATION_REVISION_CONFLICT','stale profile state cannot unrestrict');
select throws_ok($$select public.community_moderation_restrict(pg_temp.id(731),pg_temp.id(4),now(),false,null,'Reason',true)$$,'42501','COMMUNITY_RESTRICTION_TARGET_FORBIDDEN','administrator cannot restrict self or another admin');
select set_config('request.jwt.claim.sub',pg_temp.id(2)::text,true);
select throws_ok($$select pg_temp.report()$$,'42501','COMMUNITY_FORBIDDEN','restriction revokes even immutable report receipt access');
select throws_ok($$select public.community_moderation_notices()$$,'42501','COMMUNITY_FORBIDDEN','restriction revokes private decision reads');
select throws_ok($$select public.community_ui_interactions('moderation-unit',pg_temp.id(202))$$,'42501','COMMUNITY_FORBIDDEN','restriction applies to existing comment reads');
select throws_ok($$select public.community_ui_set_like('moderation-unit',pg_temp.id(740),pg_temp.id(202),true)$$,'42501','COMMUNITY_FORBIDDEN','restriction applies to existing writes');
select set_config('request.jwt.claim.sub',pg_temp.id(9)::text,true);
select lives_ok($$select public.community_moderation_notices()$$,'expired restriction automatically permits current access without Cron');
select set_config('request.jwt.claim.sub',pg_temp.id(10)::text,true);
select throws_ok($$select public.community_moderation_notices()$$,'42501','COMMUNITY_FORBIDDEN','unfinished fan profile cannot read moderation inbox');
select set_config('request.jwt.claim.sub',pg_temp.id(4)::text,true);
select lives_ok($$select public.community_moderation_restrict(pg_temp.id(732),pg_temp.id(2),(select (data->>'updated_at')::timestamptz from moderation_context where key='restriction'),false,null,'Lift restriction',true)$$,'fresh explicit action lifts user restriction');
select set_config('request.jwt.claim.sub',pg_temp.id(2)::text,true);
select lives_ok($$select public.community_moderation_notices()$$,'lifted restriction restores recipient-only access');
reset role;
select is((select count(*) from public.community_moderation_log where target_type='user' and target_id=pg_temp.id(2)),2::bigint,'restriction retry writes audit only once and lift once');
select is((select count(*) from private.notification_jobs),0::bigint,'in-app notices do not invent push consent or provider jobs');
select is((select count(*) from private.point_ledger),0::bigint,'moderation does not award or revoke rewards');
select is((select count(*) from private.notification_policy),0::bigint,'no notification delivery policy is activated');
select * from finish();
rollback;
